#!/usr/bin/env python3
"""Focused source/unit regressions for the ambiguity-band GRID10 candidate."""
from __future__ import annotations

from dataclasses import dataclass
import math
import random

from f2wp1207_grid10_ambiguity_band_candidate import (
    AmbiguityBandError,
    select_winner,
    validate_ambiguity_band,
)


@dataclass(frozen=True)
class C:
    name: str
    signal: float
    proposal_score: float


def must_raise(value):
    try:
        validate_ambiguity_band(value)
    except AmbiguityBandError:
        return
    raise AssertionError(f"expected AmbiguityBandError for {value!r}")


def main() -> None:
    # Backward compatibility: None is exactly the pre-candidate selector.
    rng = random.Random(1207)
    for n in range(1, 25):
        for _ in range(80):
            cs = tuple(
                C(str(i), rng.random(), rng.uniform(-2.0, 2.0))
                for i in range(n)
            )
            old = max(cs, key=lambda c: c.proposal_score)
            new = select_winner(cs, ambiguity_band=None)
            assert new is old

    # Reentry remains causal inside the ambiguity band.
    a = C("raw", 0.800, 0.800)
    b = C("state", 0.790, 1.390)
    assert select_winner((a, b), ambiguity_band=0.025) is b

    # But state cannot jump across the configured percept-authority bound.
    outside = C("outside", 0.774, 99.0)
    assert select_winner((a, outside), ambiguity_band=0.025) is a

    # At band=0 proposal score may decide only among exact signal ties.
    tie1 = C("tie1", 0.5, 0.6)
    tie2 = C("tie2", 0.5, 0.9)
    low = C("low", 0.499999999, 100.0)
    assert select_winner((tie1, tie2, low), ambiguity_band=0.0) is tie2

    # Hard invariant over deterministic randomized candidate sets.
    rng = random.Random(20260912)
    for band in (0.0, 0.001, 0.025, 0.05, 0.2, 1.0):
        for _ in range(5000):
            cs = tuple(
                C(str(i), rng.random(), rng.uniform(-4.0, 4.0))
                for i in range(10)
            )
            w = select_winner(cs, ambiguity_band=band)
            raw = max(c.signal for c in cs)
            assert raw - w.signal <= band + 1e-15

    for bad in (True, False, "0.025", -1e-9, 1.0000001, math.nan, math.inf, -math.inf):
        must_raise(bad)

    try:
        select_winner((), ambiguity_band=0.025)
    except AmbiguityBandError:
        pass
    else:
        raise AssertionError("empty candidate set must fail closed")

    print("PASS ambiguity-band candidate: backward compatibility + causal band + hard bound")


if __name__ == "__main__":
    main()
